            let mut copySize: size_t =
                ((64 as c_int * ((1 as c_int) << 10 as c_int)) as size_t)
                    .wrapping_sub((*dctx).tmpOutSize);
            let oldDictEnd: *const BYTE =
                (*dctx).dict.add((*dctx).dictSize).sub((*dctx).tmpOutStart);
            if (*dctx).tmpOutSize
                > (64 as c_int * ((1 as c_int) << 10 as c_int)) as size_t
            {
                copySize = 0 as size_t;
            }
            if copySize > preserveSize {
                copySize = preserveSize;
            }
            // SAFETY: source and destination ranges are valid within tmpOutBuffer/history preservation logic.
            unsafe {
                memcpy(
                    (*dctx)
                        .tmpOutBuffer
                        .add(preserveSize)
                        .sub(copySize) as *mut c_void,
                    oldDictEnd.sub(copySize) as *const c_void,
                    copySize,
                );
            }
            (*dctx).dict = (*dctx).tmpOutBuffer;
            (*dctx).dictSize = preserveSize.wrapping_add((*dctx).tmpOutStart);
        } else {
            let oldDictEnd_0: *const BYTE = (*dctx).dict.add((*dctx).dictSize);
            let newDictSize: size_t = if (*dctx).dictSize
                < (64 as c_int * ((1 as c_int) << 10 as c_int)) as size_t
            {
                (*dctx).dictSize
            } else {
                (64 as c_int * ((1 as c_int) << 10 as c_int)) as size_t
            };
            // SAFETY: source and destination ranges are valid for newDictSize bytes.
            unsafe {
                memcpy(
                    (*dctx).tmpOutBuffer as *mut c_void,
                    oldDictEnd_0.sub(newDictSize) as *const c_void,
                    newDictSize,
                );
            }
            (*dctx).dict = (*dctx).tmpOutBuffer;
            (*dctx).dictSize = newDictSize;
            (*dctx).tmpOut = (*dctx).tmpOutBuffer.add(newDictSize);
        }
    }
    *srcSizePtr = srcPtr.offset_from(srcStart) as size_t;
    *dstSizePtr_view = dstPtr.offset_from(dstStart) as size_t;
    return nextSrcSizeHint;
}
