```rust
unsafe fn LZ4F_makeBlock(
    mut dst: *mut c_void,
    mut src: *const c_void,
    mut srcSize: size_t,
    mut compress: compressFunc_t,
    mut lz4ctx: *mut c_void,
    mut level: c_int,
    mut cdict: *const LZ4F_CDict,
    mut crcFlag: LZ4F_blockChecksum_t,
) -> size_t {
    let c_size_ptr = dst as *mut BYTE;
    let data_ptr = c_size_ptr.wrapping_add(BHSize);
    let dst_capacity: c_int = if srcSize > 1 { srcSize as c_int - 1 } else { 1 };

    let mut c_size = compress.expect("non-null function pointer")(
        lz4ctx,
        src as *const c_char,
        data_ptr as *mut c_char,
        srcSize as c_int,
        dst_capacity,
        level,
        cdict,
    ) as U32;

    if c_size == 0 || (c_size as size_t) >= srcSize {
        c_size = srcSize as U32;
        LZ4F_writeLE32(
            c_size_ptr as *mut c_void,
            c_size | LZ4F_BLOCKUNCOMPRESSED_FLAG as U32,
        );
        // SAFETY: data_ptr points to the block payload area in dst, src points to srcSize readable bytes, and memcpy permits non-overlapping raw byte copy as required by the caller contract of this unsafe function.
        unsafe { memcpy(data_ptr as *mut c_void, src, srcSize) };
    } else {
        LZ4F_writeLE32(c_size_ptr as *mut c_void, c_size);
    }

    if crcFlag as u64 != 0 {
        let crc32 = XXH32(data_ptr as *const c_void, c_size as size_t, 0 as c_uint) as U32;
        let crc_ptr = data_ptr.wrapping_add(c_size as usize);
        LZ4F_writeLE32(crc_ptr as *mut c_void, crc32);
    }

    BHSize
        .wrapping_add(c_size as size_t)
        .wrapping_add((crcFlag as U32 as size_t).wrapping_mul(BFSize))
}
