#[inline(always)]
unsafe fn XXH32_update_endian(
    mut state: *mut XXH32_state_t,
    mut input: *const c_void,
    mut len: size_t,
    mut endian: XXH_endianness,
) -> XXH_errorcode {
    if input.is_null() {
        return XXH_ERROR;
    }

    let mut p = input as *const BYTE;
    // SAFETY: `input` is non-null and the caller provides a valid readable buffer of `len` bytes.
    let b_end = unsafe { p.add(len as usize) };

    let st = &mut *state;
    st.total_len_32 = (st.total_len_32 as c_uint).wrapping_add(len as c_uint) as uint32_t;
    st.large_len |=
        (((len >= 16 as size_t) as c_int) | ((st.total_len_32 >= 16 as uint32_t) as c_int))
            as uint32_t;

    let memsize = st.memsize as usize;
    if memsize + len < 16 {
        // SAFETY: destination is within `st.mem32` tail by `memsize`, source is `input`,
        // and copy length is `< 16 - memsize`, so both regions are valid and non-overlapping.
        unsafe {
            XXH_memcpy(
                (st.mem32.as_mut_ptr() as *mut BYTE).add(memsize) as *mut c_void,
                input,
                len,
            );
        }
        st.memsize = (st.memsize as c_uint).wrapping_add(len as c_uint) as uint32_t;
        return XXH_OK;
    }

    if memsize != 0 {
        let fill = 16usize - memsize;
        // SAFETY: destination fills the remaining bytes of `st.mem32`, source has at least `fill`
        // bytes because `memsize + len >= 16`, and regions do not overlap.
        unsafe {
            XXH_memcpy(
                (st.mem32.as_mut_ptr() as *mut BYTE).add(memsize) as *mut c_void,
                input,
                fill as size_t,
            );
        }

        let mut p32 = st.mem32.as_ptr();
        st.v1 = XXH32_round(st.v1 as U32, XXH_readLE32(p32 as *const c_void, endian)) as uint32_t;
        // SAFETY: `p32` points into the 4-element `mem32` array.
        p32 = unsafe { p32.add(1) };
        st.v2 = XXH32_round(st.v2 as U32, XXH_readLE32(p32 as *const c_void, endian)) as uint32_t;
        // SAFETY: `p32` points into the 4-element `mem32` array.
        p32 = unsafe { p32.add(1) };
        st.v3 = XXH32_round(st.v3 as U32, XXH_readLE32(p32 as *const c_void, endian)) as uint32_t;
        // SAFETY: `p32` points into the 4-element `mem32` array.
        p32 = unsafe { p32.add(1) };
        st.v4 = XXH32_round(st.v4 as U32, XXH_readLE32(p32 as *const c_void, endian)) as uint32_t;

        // SAFETY: we just consumed `fill` bytes from `p`, and `fill <= len`.
        p = unsafe { p.add(fill) };
        st.memsize = 0;
    }

    let remaining = b_end as usize - p as usize;
    if remaining >= 16 {
        let mut v1 = st.v1 as U32;
        let mut v2 = st.v2 as U32;
        let mut v3 = st.v3 as U32;
        let mut v4 = st.v4 as U32;

        let mut n = remaining / 16;
        loop {
            v1 = XXH32_round(v1, XXH_readLE32(p as *const c_void, endian));
            // SAFETY: loop invariant guarantees at least 16 readable bytes remain in this iteration.
            p = unsafe { p.add(4) };
            v2 = XXH32_round(v2, XXH_readLE32(p as *const c_void, endian));
            // SAFETY: loop invariant guarantees at least 16 readable bytes remain in this iteration.
            p = unsafe { p.add(4) };
            v3 = XXH32_round(v3, XXH_readLE32(p as *const c_void, endian));
            // SAFETY: loop invariant guarantees at least 16 readable bytes remain in this iteration.
            p = unsafe { p.add(4) };
            v4 = XXH32_round(v4, XXH_readLE32(p as *const c_void, endian));
            // SAFETY: loop invariant guarantees at least 16 readable bytes remain in this iteration.
            p = unsafe { p.add(4) };

            n -= 1;
            if n == 0 {
                break;
            }
        }

        st.v1 = v1 as uint32_t;
        st.v2 = v2 as uint32_t;
        st.v3 = v3 as uint32_t;
        st.v4 = v4 as uint32_t;
    }

    if p < b_end {
        let tail = b_end as usize - p as usize;
        // SAFETY: destination is the start of `st.mem32` with capacity 16 bytes, source tail length is `< 16`,
        // and regions do not overlap.
        unsafe {
            XXH_memcpy(
                st.mem32.as_mut_ptr() as *mut c_void,
                p as *const c_void,
                tail as size_t,
            );
        }
        st.memsize = tail as c_uint as uint32_t;
    }

    XXH_OK
}
