#[inline(always)]
unsafe fn XXH32_endian_align(
    mut input: *const c_void,
    mut len: size_t,
    mut seed: U32,
    mut endian: XXH_endianness,
    mut align: XXH_alignment,
) -> U32 {
    let mut p = input as *const BYTE;
    let b_end = p.wrapping_add(len as usize);

    let mut h32: U32;
    if len >= 16 as size_t {
        let limit = b_end.wrapping_sub(15);
        let mut v1 = seed.wrapping_add(PRIME32_1).wrapping_add(PRIME32_2);
        let mut v2 = seed.wrapping_add(PRIME32_2);
        let mut v3 = seed;
        let mut v4 = seed.wrapping_sub(PRIME32_1);

        loop {
            v1 = XXH32_round(v1, XXH_readLE32_align(p as *const c_void, endian, align));
            p = p.wrapping_add(4);
            v2 = XXH32_round(v2, XXH_readLE32_align(p as *const c_void, endian, align));
            p = p.wrapping_add(4);
            v3 = XXH32_round(v3, XXH_readLE32_align(p as *const c_void, endian, align));
            p = p.wrapping_add(4);
            v4 = XXH32_round(v4, XXH_readLE32_align(p as *const c_void, endian, align));
            p = p.wrapping_add(4);

            if p >= limit {
                break;
            }
        }

        h32 = v1.rotate_left(1)
            .wrapping_add(v2.rotate_left(7))
            .wrapping_add(v3.rotate_left(12))
            .wrapping_add(v4.rotate_left(18));
    } else {
        h32 = seed.wrapping_add(PRIME32_5);
    }

    h32 = h32.wrapping_add(len as U32);
    XXH32_finalize(
        h32,
        p as *const c_void,
        len & 15 as size_t,
        endian,
        align,
    )
}
