#[inline(always)]
unsafe fn LZ4HC_Insert(mut hc4: *mut LZ4HC_CCtx_internal, mut ip_0: *const BYTE) {
    let chain_table: *mut U16 = &raw mut (*hc4).chainTable as *mut U16;
    let hash_table: *mut U32 = &raw mut (*hc4).hashTable as *mut U32;
    let prefix_ptr: *const BYTE = (*hc4).prefixStart as *const BYTE;
    let prefix_idx: U32 = (*hc4).dictLimit as U32;
    let target: U32 =
        (ip_0.offset_from(prefix_ptr) as c_long as U32).wrapping_add(prefix_idx);
    let mut idx: U32 = (*hc4).nextToUpdate as U32;

    if idx >= target {
        (*hc4).nextToUpdate = target as LZ4_u32;
        return;
    }

    let base = prefix_ptr.wrapping_offset(-(prefix_idx as isize));

    while idx < target {
        let p = base.wrapping_offset(idx as isize);
        let h: U32 = LZ4HC_hashPtr(p as *const c_void) as U32;

        // SAFETY: `h` is produced by `LZ4HC_hashPtr` for the LZ4HC hash table size, so it is a valid index into `hashTable`.
        let hash_slot = unsafe { hash_table.add(h as usize) };
        // SAFETY: `hash_slot` points within `hashTable`.
        let prev = unsafe { *hash_slot };
        let delta = idx.wrapping_sub(prev);
        let clamped = if delta > LZ4_DISTANCE_MAX as U32 {
            LZ4_DISTANCE_MAX as U32
        } else {
            delta
        };

        // SAFETY: indexing uses `idx as U16`, matching the original ring-buffer semantics of `chainTable` size 65536.
        unsafe { *chain_table.add(idx as u16 as usize) = clamped as U16 };
        // SAFETY: `hash_slot` points within `hashTable`.
        unsafe { *hash_slot = idx };

        idx = idx.wrapping_add(1);
    }

    (*hc4).nextToUpdate = target as LZ4_u32;
}
