unsafe fn LZ4F_compressUpdateImpl(
    mut cctxPtr: *mut LZ4F_cctx,
    mut dstBuffer: *mut c_void,
    mut dstCapacity: size_t,
    mut srcBuffer: *const c_void,
    mut srcSize: size_t,
    mut compressOptionsPtr: *const LZ4F_compressOptions_t,
    mut blockCompression: LZ4F_BlockCompressMode_e,
) -> size_t {
    let cctx = &mut *cctxPtr;
    let blockSize: size_t = cctx.maxBlockSize;
    let mut srcPtr: *const BYTE = srcBuffer as *const BYTE;
    let srcEnd: *const BYTE = if srcSize != 0 {
        srcPtr.offset(srcSize as isize)
    } else {
        srcPtr
    };
    let dstStart: *mut BYTE = dstBuffer as *mut BYTE;
    let mut dstPtr: *mut BYTE = dstStart;
    let mut lastBlockCompressed: LZ4F_lastBlockStatus = notDone;

    if cctx.cStage != 1 as U32 {
        return LZ4F_returnErrorCode(LZ4F_ERROR_compressionState_uninitialized) as size_t;
    }

    if dstCapacity < LZ4F_compressBound_internal(srcSize, &raw mut cctx.prefs, cctx.tmpInSize) {
        return LZ4F_returnErrorCode(LZ4F_ERROR_dstMaxSize_tooSmall) as size_t;
    }

    if blockCompression as c_uint == LZ4B_UNCOMPRESSED as c_int as c_uint && dstCapacity < srcSize {
        return LZ4F_returnErrorCode(LZ4F_ERROR_dstMaxSize_tooSmall) as size_t;
    }

    if cctx.blockCompressMode as c_uint != blockCompression as c_uint {
        let bytesWritten = LZ4F_flush(cctxPtr, dstBuffer, dstCapacity, compressOptionsPtr);
        dstPtr = dstPtr.offset(bytesWritten as isize);
        cctx.blockCompressMode = blockCompression;
    }

    if compressOptionsPtr.is_null() {
        compressOptionsPtr = &raw const k_cOptionsNull;
    }

    let prefs = &cctx.prefs;
    let frame_info = &prefs.frameInfo;
    let compression_level = prefs.compressionLevel;
    let block_checksum = frame_info.blockChecksumFlag;
    let block_mode = frame_info.blockMode;
    let auto_flush = prefs.autoFlush;
    let lz4_ctx = cctx.lz4CtxPtr;
    let cdict = cctx.cdict;

    let compress: compressFunc_t =
        LZ4F_selectCompression(block_mode, compression_level, blockCompression) as compressFunc_t;

    if cctx.tmpInSize > 0 {
        let sizeToCopy: size_t = blockSize.wrapping_sub(cctx.tmpInSize);
        if sizeToCopy > srcSize {
            memcpy(
                cctx.tmpIn.offset(cctx.tmpInSize as isize) as *mut c_void,
                srcBuffer,
                srcSize,
            );
            srcPtr = srcEnd;
            cctx.tmpInSize = cctx.tmpInSize.wrapping_add(srcSize);
        } else {
            lastBlockCompressed = fromTmpBuffer;
            memcpy(
                cctx.tmpIn.offset(cctx.tmpInSize as isize) as *mut c_void,
                srcBuffer,
                sizeToCopy,
            );
            srcPtr = srcPtr.offset(sizeToCopy as isize);
            dstPtr = dstPtr.offset(
                LZ4F_makeBlock(
                    dstPtr as *mut c_void,
                    cctx.tmpIn as *const c_void,
                    blockSize,
                    compress,
                    lz4_ctx,
                    compression_level,
                    cdict,
                    block_checksum,
                ) as isize,
            );
            if block_mode as c_uint == LZ4F_blockLinked as c_int as c_uint {
                cctx.tmpIn = cctx.tmpIn.offset(blockSize as isize);
            }
            cctx.tmpInSize = 0;
        }
    }

    while srcEnd.offset_from(srcPtr) as c_long as size_t >= blockSize {
        lastBlockCompressed = fromSrcBuffer;
        dstPtr = dstPtr.offset(
            LZ4F_makeBlock(
                dstPtr as *mut c_void,
                srcPtr as *const c_void,
                blockSize,
                compress,
                lz4_ctx,
                compression_level,
                cdict,
                block_checksum,
            ) as isize,
        );
        srcPtr = srcPtr.offset(blockSize as isize);
    }

    if auto_flush != 0 && srcPtr < srcEnd {
        lastBlockCompressed = fromSrcBuffer;
        dstPtr = dstPtr.offset(
            LZ4F_makeBlock(
                dstPtr as *mut c_void,
                srcPtr as *const c_void,
                srcEnd.offset_from(srcPtr) as c_long as size_t,
                compress,
                lz4_ctx,
                compression_level,
                cdict,
                block_checksum,
            ) as isize,
        );
        srcPtr = srcEnd;
    }

    if block_mode as c_uint == LZ4F_blockLinked as c_int as c_uint
        && lastBlockCompressed as c_uint == fromSrcBuffer as c_int as c_uint
    {
        if (*compressOptionsPtr).stableSrc != 0 {
            cctx.tmpIn = cctx.tmpBuff;
        } else {
            LZ4F_localSaveDict(cctxPtr as *mut LZ4F_cctx_t);
        }
    }

    if auto_flush == 0
        && cctx.tmpIn.offset(blockSize as isize) > cctx.tmpBuff.offset(cctx.maxBufferSize as isize)
    {
        LZ4F_localSaveDict(cctxPtr as *mut LZ4F_cctx_t);
    }

    if srcPtr < srcEnd {
        let sizeToCopy_0: size_t = srcEnd.offset_from(srcPtr) as c_long as size_t;
        memcpy(cctx.tmpIn as *mut c_void, srcPtr as *const c_void, sizeToCopy_0);
        cctx.tmpInSize = sizeToCopy_0;
    }

    if frame_info.contentChecksumFlag as c_uint == LZ4F_contentChecksumEnabled as c_int as c_uint {
        XXH32_update(&raw mut cctx.xxh, srcBuffer, srcSize);
    }

    cctx.totalInSize = (cctx.totalInSize as c_ulong).wrapping_add(srcSize as c_ulong) as U64;
    dstPtr.offset_from(dstStart) as c_long as size_t
}
