unsafe fn LZ4_putIndexOnHash(
    idx: U32,
    h: U32,
    tableBase: *mut c_void,
    tableType: tableType_t,
) {
    let p = (tableBase as *mut u8).wrapping_add(h as usize * 4);
    match tableType as c_uint {
        2 => {
            // SAFETY: Preserves original semantics for tableType==2: caller provides a valid U32 hash table and h is an in-bounds element index.
            *(p as *mut U32) = idx;
        }
        3 => {
            // SAFETY: Preserves original semantics for tableType==3: caller provides a valid U16 hash table and h is an in-bounds element index; byte offset h*4 matches the original cast-before-offset behavior.
            *(p as *mut U16) = idx as U16;
        }
        _ => {}
    }
}
