#[inline(always)]
fn LZ4_hash5(mut sequence: U64, tableType: tableType_t) -> U32 {
    let hash_log = if tableType as c_uint == byU16 as c_int as c_uint {
        (LZ4_HASHLOG + 1) as u32
    } else {
        LZ4_HASHLOG as u32
    };

    if cfg!(target_endian = "little") {
        const PRIME5BYTES: u64 = 889523592379u64;
        ((sequence << 24).wrapping_mul(PRIME5BYTES) >> (64u32 - hash_log)) as U32
    } else {
        const PRIME8BYTES: u64 = 11400714785074694791u64;
        ((sequence >> 24).wrapping_mul(PRIME8BYTES) >> (64u32 - hash_log)) as U32
    }
}
